mapper.select:
select p.id, p.name, p.merchant_id, p.category_id, p.brand_id, p.main_image, p.status, p.deleted, p.update_time, b.name as brandName, c.name as categoryName, mp.shop_name as merchantName, sku_agg.min_price as minPrice, sku_agg.total_stock as totalStock from product p left join merchant_profile mp on p.merchant_id = mp.user_id left join brand b on p.brand_id = b.id left join category c on p.category_id = c.id left join ( select product_id, min(price) as min_price, sum(stock) as total_stock from product_sku where deleted = 0 group by product_id ) sku_agg on p.id = sku_agg.product_id
and p.deleted = #{dto.deleted}
and p.name like concat('%', #{dto.keyword}, '%')
and p.category_id = #{dto.categoryId}
and p.brand_id = #{dto.brandId}
and p.status = #{dto.status}
and p.merchant_id = #{dto.merchantId}
order by p.create_time desc

select name from product
where name = #{name}
and merchant_id = #{merchantId}

    and id != #{productId}

limit 1
